+        duplicatesAndNegatives();
+        adversarialInputsDoNotOverflow();
+        randomizedAgainstReference();
+        genericNaturalOrder();
+        genericWithComparator();
+        nullArgumentsRejected();
+
+        System.out.printf("%n%d passed, %d failed%n", passed, failed);
+        if (failed > 0) {
+            System.exit(1);
+        }
+    }
